	<style>
		*{box-sizing:border-box}body{min-height:100vh;margin:0;background:radial-gradient(circle at 15% 10%,#4ade8040,transparent 25rem),linear-gradient(135deg,#064e3b,#0f766e 55%,#115e59);color:#fff;font-family:'Plus Jakarta Sans',sans-serif}.top{display:flex;align-items:center;justify-content:space-between;padding:13px 20px;background:#062f2acc;border-bottom:1px solid #ffffff1f}.top a{color:#d1fae5;text-decoration:none;font-size:.85rem;font-weight:700}.top strong{font-size:.9rem}.shell{display:flex;min-height:calc(100vh - 53px);align-items:center;justify-content:center;padding:24px 16px}.game{width:min(100%,38rem);text-align:center}.hud{display:flex;justify-content:space-between;gap:.75rem;margin-bottom:1rem}.hud div{min-width:0;flex:1;padding:.75rem;border:1px solid #ffffff24;border-radius:13px;background:#ffffff12}.hud b{display:block;font-size:1.25rem}.hud span{color:#d1fae5;font-size:.62rem;font-weight:800;letter-spacing:.05em;text-transform:uppercase}.progress{height:8px;overflow:hidden;margin:0 0 1.5rem;border-radius:99px;background:#ffffff21}.progress i{display:block;height:100%;background:linear-gradient(90deg,#bbf7d0,#fef08a);transition:width .25s}.card{padding:clamp(1.4rem,5vw,2.4rem);border:1px solid #ffffff26;border-radius:25px;background:#ffffff13;box-shadow:0 20px 55px #022c223d;backdrop-filter:blur(12px)}.card .eyebrow{color:#bbf7d0;font-size:.67rem;font-weight:900;letter-spacing:.09em;text-transform:uppercase}.clue{min-height:2.7rem;margin:.5rem auto 1rem;color:#ecfdf5;font-size:.9rem;line-height:1.55}.letters{display:flex;justify-content:center;gap:.42rem;flex-wrap:wrap;min-height:4.2rem;margin:1.25rem 0}.letters span{display:grid;min-width:2.5rem;height:3rem;place-items:center;border:1px solid #ffffff35;border-radius:10px;background:#ffffffed;color:#115e59;font-size:1.3rem;font-weight:900;box-shadow:0 6px 16px #022c224d}.answer{width:min(100%,22rem);border:2px solid #ffffff55;border-radius:12px;background:#ffffffed;color:#064e3b;font:800 1.05rem inherit;letter-spacing:.08em;padding:.85rem 1rem;text-align:center;text-transform:uppercase;outline:0}.answer:focus{border-color:#fef08a;box-shadow:0 0 0 4px #fef08a33}.actions{display:flex;gap:.65rem;justify-content:center;margin-top:1rem}.btn{border:0;border-radius:11px;padding:.78rem 1rem;cursor:pointer;font:800 .82rem inherit}.btn-main{background:#fef08a;color:#365314}.btn-muted{background:#ffffff1a;color:#fff;border:1px solid #ffffff35}.feedback{height:1.35rem;margin-top:.8rem;color:#fef08a;font-size:.78rem;font-weight:800}.overlay{position:fixed;inset:0;z-index:5;display:grid;place-items:center;padding:1rem;background:#022c22b8;backdrop-filter:blur(7px)}.overlay.hidden{display:none}.dialog{width:min(100%,25rem);padding:2rem;border-radius:22px;background:#fff;color:#134e4a;text-align:center;box-shadow:0 25px 60px #001b15}.dialog h1{margin:.25rem 0 .5rem;font-size:1.7rem}.dialog p{color:#52736e;font-size:.82rem;line-height:1.6}.dialog .btn{width:100%;margin-top:.55rem}.result{display:grid;grid-template-columns:repeat(2,1fr);gap:.65rem;margin:1rem 0}.result div{padding:.7rem;border-radius:10px;background:#f0fdf4}.result b{display:block;font-size:1.25rem}@media(max-width:480px){.top strong{max-width:12rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.shell{padding:16px 12px}.card{padding:1.25rem}.letters span{min-width:2.2rem;height:2.7rem}.hud b{font-size:1rem}}
