<body>
	<div class="top"><a href="<?= base_url('belajar/pilih/word_scramble'); ?>">← Pilih Set</a><strong><?= html_escape($set['name']); ?></strong><span></span></div>
	<div class="shell"><main class="game"><div class="hud"><div><b id="round">0/<?= count($content); ?></b><span>Kata</span></div><div><b id="score">0</b><span>Skor</span></div><div><b id="time"><?= $seconds_per_word; ?></b><span>Detik</span></div></div><div class="progress"><i id="bar" style="width:100%"></i></div><section class="card"><div class="eyebrow">Susun huruf menjadi kata yang tepat</div><p class="clue" id="clue"></p><div class="letters" id="letters"></div><form id="answerForm"><input class="answer" id="answer" autocomplete="off" autocapitalize="characters" placeholder="Ketik jawaban" aria-label="Jawaban kata"></form><div class="actions"><button class="btn btn-main" id="check" type="button">Periksa Jawaban</button><button class="btn btn-muted" id="skip" type="button">Lewati</button></div><div class="feedback" id="feedback"></div></section></main></div>
	<div class="overlay" id="start"><div class="dialog"><div style="font-size:3rem">🔤</div><h1>Susun Kata</h1><p><strong><?= html_escape($set['name']); ?></strong><br>Susun huruf yang diacak berdasarkan petunjuk. Setiap kata memiliki waktu <?= $seconds_per_word; ?> detik.</p><button class="btn btn-main" id="play">Mulai Bermain</button><button class="btn btn-muted" onclick="history.back()">Kembali</button></div></div>
	<div class="overlay hidden" id="end"><div class="dialog"><div style="font-size:3rem">🎉</div><h1>Selesai!</h1><div class="result"><div><b id="finalScore">0</b><span>Skor</span></div><div><b id="finalCorrect">0</b><span>Benar</span></div></div><p id="resultText"></p><?php if(!empty($next_game)): ?><button class="btn btn-main" onclick="location.href='<?= base_url($next_game['url']); ?>'">Coba <?= html_escape($next_game['name']); ?> →</button><?php endif; ?><button class="btn btn-muted" onclick="location.href='<?= base_url('belajar/pilih/word_scramble'); ?>'">Pilih Materi Lain</button></div></div>
	<script>
	const WORDS=<?= json_encode(array_map(function($item){ return ['word'=>mb_strtoupper(trim((string)$item['term']),'UTF-8'),'clue'=>$item['definition']]; },$content),JSON_UNESCAPED_UNICODE); ?>, LIMIT=<?= $seconds_per_word; ?>, FINISH='<?= base_url('belajar/finish'); ?>', SET=<?= (int)$set['id']; ?>;
	let index=0,score=0,correct=0,remaining=LIMIT,timer=null,startedAt=0,locked=false;
	const el=id=>document.getElementById(id);
	function scramble(word){let a=[...word];for(let n=0;n<8;n++){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}}return a.join('')===word&&a.length>1?[...word].reverse().join(''):a.join('')}
	function render(){if(index>=WORDS.length)return finish();locked=false;remaining=LIMIT;const w=WORDS[index];el('round').textContent=(index+1)+'/'+WORDS.length;el('clue').textContent=w.clue;el('letters').innerHTML=[...scramble(w.word)].map(c=>'<span>'+c+'</span>').join('');el('answer').value='';el('answer').focus();el('feedback').textContent='';paint();clearInterval(timer);timer=setInterval(()=>{remaining--;paint();if(remaining<=0){clearInterval(timer);feedback('Waktu habis. Jawabannya: '+w.word,false);setTimeout(next,1100)}},1000)}
	function paint(){el('time').textContent=remaining;el('bar').style.width=(remaining/LIMIT*100)+'%'}
	function normalize(v){return v.toLocaleUpperCase('id-ID').replace(/[^A-Z0-9]/g,'')}
	function feedback(text,ok){el('feedback').textContent=text;el('feedback').style.color=ok?'#bbf7d0':'#fef08a'}
	function check(){if(locked||index>=WORDS.length)return;const answer=normalize(el('answer').value),word=normalize(WORDS[index].word);if(!answer){feedback('Ketik jawaban terlebih dahulu.',false);return}if(answer===word){locked=true;clearInterval(timer);correct++;score+=100+remaining*2;el('score').textContent=score;feedback('Benar! +'+(100+remaining*2)+' poin',true);setTimeout(next,650)}else{feedback('Belum tepat, coba lagi.',false);el('answer').select()}}
	function next(){index++;render()}
	function finish(){clearInterval(timer);el('finalScore').textContent=score;el('finalCorrect').textContent=correct+'/'+WORDS.length;el('resultText').textContent=correct===WORDS.length?'Hebat, semua kata berhasil disusun!':'Terus berlatih, kamu sudah menyelesaikan permainan.';el('end').classList.remove('hidden');const duration=Math.max(5,Math.round((Date.now()-startedAt)/1000));fetch(FINISH,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams({game_code:'word_scramble',set_id:SET,score:score,max_score:WORDS.length*(100+LIMIT*2),duration_seconds:duration})}).catch(()=>{})}
	el('play').onclick=()=>{el('start').classList.add('hidden');startedAt=Date.now();render()};el('check').onclick=check;el('skip').onclick=()=>{if(!locked){locked=true;clearInterval(timer);feedback('Jawabannya: '+WORDS[index].word,false);setTimeout(next,800)}};el('answerForm').onsubmit=e=>{e.preventDefault();check()};
	</script>
</body></html>
